#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * Reimplementation of the original obfuscated binary "prog58_turing_increment".
 * The program behaves like a tiny Turing‑machine that increments a binary
 * string supplied as the first command‑line argument.
 *
 * Output rules (exactly as the original binary):
 *   * If the argument is missing, empty, longer than 31 characters, or contains
 *     any character other than '0' or '1' → prints "INVALID_INPUT\n".
 *   * If the string consists solely of '1' characters → prints "OVERFLOW\n".
 *   * Otherwise it prints the incremented binary string prefixed by "result="
 *     (no newline), then a space and "steps=%lu\n" where the step count is the
 *     number of head moves performed by the simulated Turing‑machine.
 *
 * The step count equals (len‑1) moves to the rightmost cell plus the number of
 * trailing '1's (the left‑ward carry moves). This matches the behaviour of the
 * original state‑machine implementation.
 */

static void increment_binary(const char *input)
{
    size_t len = strlen(input);

    /* ----- validation --------------------------------------------------- */
    if (len == 0 || len > 31) {               // empty or too long
        puts("INVALID_INPUT");
        return;
    }
    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return;
        }
    }

    /* ----- overflow detection (all '1's) ------------------------------- */
    int all_ones = 1;
    for (size_t i = 0; i < len; ++i) {
        if (input[i] == '0') { all_ones = 0; break; }
    }
    if (all_ones) {
        puts("OVERFLOW");
        return;
    }

    /* ----- perform increment -------------------------------------------- */
    char *tape = malloc(len + 1);
    if (!tape) { perror("malloc"); exit(EXIT_FAILURE); }
    memcpy(tape, input, len + 1);

    // Count trailing '1's – these are the bits that will flip to '0' and cause a left move.
    size_t trailing_ones = 0;
    while (trailing_ones < len && tape[len - 1 - trailing_ones] == '1')
        ++trailing_ones;

    // Flip the first '0' encountered from the right to '1'.
    tape[len - 1 - trailing_ones] = '1';
    // Turn the trailing '1's into '0's.
    for (size_t i = 0; i < trailing_ones; ++i)
        tape[len - 1 - i] = '0';

    // Steps = moves to the rightmost cell + left moves while carrying.
    unsigned long steps = (len > 0 ? len - 1 : 0) + trailing_ones;

    printf("result=%s steps=%lu\n", tape, steps);
    free(tape);
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    increment_binary(argv[1]);
    return 0;
}
